begin;
select no_plan();
update public.plans set prova_monthly_exams=null where code='free';
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000003601','progress-3601@test.local');
insert into public.families(id,name,created_by,timezone) values('00000000-0000-4000-8000-000000003611','Fixture','00000000-0000-4000-8000-000000003601','Europe/Istanbul');
insert into public.family_members(family_id,user_id) values('00000000-0000-4000-8000-000000003611','00000000-0000-4000-8000-000000003601');
insert into public.children(id,family_id,name,grade) values('00000000-0000-4000-8000-000000003621','00000000-0000-4000-8000-000000003611','Fixture',5);
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000003602','progress-3602@test.local');
insert into public.families(id,name,created_by,timezone) values('00000000-0000-4000-8000-000000003612','Fixture','00000000-0000-4000-8000-000000003602','Europe/Istanbul');
insert into public.family_members(family_id,user_id) values('00000000-0000-4000-8000-000000003612','00000000-0000-4000-8000-000000003602');
insert into public.children(id,family_id,name,grade) values('00000000-0000-4000-8000-000000003622','00000000-0000-4000-8000-000000003612','Fixture',5);

create function pg_temp.event_values(title text default 'Okuma saati', child text default '00000000-0000-4000-8000-000000003621') returns jsonb language sql as $$ select jsonb_build_object('title',title,'type','activity','child_id',child,'starts_at','2026-11-04T15:00:00Z','ends_at','2026-11-04T15:30:00Z','all_day',false,'location',null,'rrule',null) $$;
create function pg_temp.save_event(req uuid,rev int,body jsonb) returns jsonb language sql as $$select public.save_calendar_event(req,'00000000-0000-4000-8000-000000004601',rev,body)$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003601","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003611","role":"parent"}}',true);
select is(pg_temp.save_event('00000000-0000-4000-8000-000000004611',0,pg_temp.event_values())->>'revision','1','create returns first revision');
select is(pg_temp.save_event('00000000-0000-4000-8000-000000004611',0,pg_temp.event_values())->>'revision','1','lost create reply replays');
select is((select count(*)::int from public.events where id='00000000-0000-4000-8000-000000004601'),1,'no duplicate event');
select throws_ok($$select pg_temp.save_event('00000000-0000-4000-8000-000000004611',0,pg_temp.event_values('Different'))$$,'P0001','request_conflict','receipt cannot carry changed form');
select throws_ok($$select pg_temp.save_event(gen_random_uuid(),0,pg_temp.event_values())$$,'P0001','event_changed','new request cannot overwrite existing id');
select is(pg_temp.save_event('00000000-0000-4000-8000-000000004612',1,pg_temp.event_values('Yeni başlık'))->>'revision','2','update advances revision');
select is(pg_temp.save_event('00000000-0000-4000-8000-000000004611',0,pg_temp.event_values())->>'revision','1','old successful request can replay after later edit');
select is((select title from public.events where id='00000000-0000-4000-8000-000000004601'),'Yeni başlık','replay does not revert later edit');
select throws_ok($$select pg_temp.save_event(gen_random_uuid(),1,pg_temp.event_values())$$,'P0001','event_changed','stale edit blocked');
update public.events set location='Okul' where id='00000000-0000-4000-8000-000000004601';
select is((select edit_revision from public.events where id='00000000-0000-4000-8000-000000004601'),3,'legacy direct update also advances revision');
select throws_ok($$select pg_temp.save_event(gen_random_uuid(),2,null)$$,'P0001','event_changed','stale deletion blocked');
select throws_ok($$select pg_temp.save_event(gen_random_uuid(),3,pg_temp.event_values('Test','00000000-0000-4000-8000-000000003622'))$$,'42501','forbidden','other family child forbidden');
select throws_ok($$insert into public.events(family_id,child_id,title,starts_at) values('00000000-0000-4000-8000-000000003611','00000000-0000-4000-8000-000000003622','Invalid',now())$$,'42501',null,'direct policy also blocks foreign child');
select throws_ok($$select pg_temp.save_event(gen_random_uuid(),3,pg_temp.event_values()||'{"family_id":"00000000-0000-4000-8000-000000003612"}')$$,'P0001','invalid_input','foreign/unknown fields rejected');
select throws_ok($$select pg_temp.save_event(gen_random_uuid(),3,pg_temp.event_values()||'{"ends_at":"2026-11-03T15:00:00Z"}')$$,'P0001','invalid_input','negative duration rejected');
select throws_ok($$select pg_temp.save_event(gen_random_uuid(),3,pg_temp.event_values()||'{"starts_at":"infinity"}')$$,'P0001','invalid_input','nonfinite time rejected');
select throws_ok($$select pg_temp.save_event(gen_random_uuid(),3,pg_temp.event_values()||'{"rrule":"FREQ=SECONDLY"}')$$,'P0001','invalid_input','unsupported new recurrence rejected');
select throws_ok($$select pg_temp.save_event(gen_random_uuid(),3,pg_temp.event_values()||'{"all_day":null}')$$,'P0001','invalid_input','json null cannot bypass boolean');
select is(pg_temp.save_event('00000000-0000-4000-8000-000000004613',3,null)->>'deleted','true','delete succeeds once');
select is(pg_temp.save_event('00000000-0000-4000-8000-000000004613',3,null)->>'deleted','true','lost deletion reply replays');
select is((select count(*)::int from public.events where id='00000000-0000-4000-8000-000000004601'),0,'event deleted');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003602","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003612","role":"parent"}}',true);
select throws_ok($$select pg_temp.save_event('00000000-0000-4000-8000-000000004611',0,pg_temp.event_values())$$,'P0001','request_conflict','other family cannot replay receipt');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003601","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003611","role":"device","child_id":"00000000-0000-4000-8000-000000003621"}}',true);
select throws_ok($$select pg_temp.save_event(gen_random_uuid(),0,pg_temp.event_values())$$,'42501','forbidden','device cannot invoke parent editor');
reset role;
select ok(not has_function_privilege('anon','public.save_calendar_event(uuid,uuid,int,jsonb)','EXECUTE'),'anonymous blocked');
select * from finish();
rollback;
